  let originTop = -window.scrollY;
  if (!isPageRelative) {
    const parentRect = parent.getBoundingClientRect();
    originLeft = parentRect.left + parent.clientLeft - parent.scrollLeft;
    originTop = parentRect.top + parent.clientTop - parent.scrollTop;
  }
